impl Solution{pub fn largest_divisible_subset(mut a:Vec<i32>)->Vec<i32>{if a.is_empty(){return vec![]}a.sort();let n=a.len();let(mut d,mut p,mut best)=(vec![1;n],vec![usize::MAX;n],0);for i in 0..n{for j in 0..i{if a[i]%a[j]==0&&d[j]+1>d[i]{d[i]=d[j]+1;p[i]=j}}if d[i]>d[best]{best=i}}let mut o=vec![];let mut i=best;loop{o.push(a[i]);if p[i]==usize::MAX{break}i=p[i]}o.reverse();o}}
